import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第19章 你还在","description":"","frontmatter":{},"headers":[],"relativePath":"第19章_你还在.md","filePath":"第19章_你还在.md"}'),r={name:"第19章_你还在.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第19章-你还在" tabindex="-1">第19章 你还在 <a class="header-anchor" href="#第19章-你还在" aria-label="Permalink to &quot;第19章 你还在&quot;">​</a></h1><p>她回来那天，是腊月十六。</p><p>那年腊月来得早。奶奶从月初就开始备年货，存了腊肉，晒了萝卜干，还找人帮忙搬了两箱橘子。她说今年要包粽子，我说又不是端午，她说想吃就包。</p><p>那阵子我白天帮她干活，晚上写作业。写得比平常快，因为没别的事可做。</p><p>那天晚上我在写寒假作业。奶奶睡了，客厅里只开了一盏小灯。我在做数学，做到第三页的时候手机在桌角亮了。</p><p>我没有马上去看。那阵子我已经养成了习惯，手机响了也不看，因为大部分是群消息。</p><p>我又写了两道题，才把手伸过去。</p><p>屏幕上是一个名字。</p><p>我盯着那个名字看了一会儿，手指有点不听使唤。我点开。</p><p>她说：你怎么还没删我。</p><p>我坐在那里，笔还捏在手里。我看了三遍这句话。</p><p>我先站起来去洗了个手。手心里全是汗，握不住手机。洗手的时候水流了很久，我把手在裤子上擦了一下，才回去拿。</p><p>我回：你为什么这么问。</p><p>她隔了两分钟。</p><p>她说：我以为你早就删了。</p><p>我说：我没删。</p><p>她说：为什么不删。</p><p>我说：我为什么要删。</p><p>她说：你不生气吗。</p><p>我那时候才发现自己在发抖，不是气的，是那种一下子松下来的抖。</p><p>我回了一句：你去哪儿了。</p><p>她过了一会儿回。</p><p>她说：家里的事。</p><p>就四个字。</p><p>我等着她往下说。她没有。屏幕停在那四个字上，后面什么也没有。</p><p>过了几分钟，她发来一句。</p><p>她说：你不问吗。</p><p>我说：问什么。</p><p>她说：问我这半年去哪了。</p><p>我说：你说了，家里的事。</p><p>她说：就这样？</p><p>我说：就这样。</p><p>她那边安静了很久。我以为她生气了，正准备补一句什么，她发来一个字。</p><p>她说：哦。</p><p>然后她说：那我下了。</p><p>我说：好。</p><p>她没有下。过了一会儿，她又发来一条。</p><p>她说：你就这么让我走了。</p><p>我说：你没走，你还在。</p><p>她说：你这人。</p><p>那天晚上她待到了两点。</p><p>她没说这半年的事。我也没问。她讲的全是些很碎的东西，讲她最近在看的一部剧，讲她楼下那家店换了老板，讲她新买的一支笔漏墨。她说得很随意，像是昨天刚聊过。</p><p>我一条一条接。接的时候我在想一件事：她好像根本没消失过。</p><p>她说话的方式跟以前一模一样。她的标点、她的断句、她连发几条的习惯，一点都没变。中间空了半年，可那半年像被人从日历上撕掉了，撕得干干净净。</p><p>快两点的时候，她说要睡了。</p><p>我说好。</p><p>她说：明天还能聊吗。</p><p>我说：能。</p><p>她说：你要是在的话我就来。</p><p>我说：我在。</p><p>她说：嗯。</p><p>她说：那晚安。</p><p>我说：晚安。</p><p>她下线之后，我把手机放在桌上，没关灯。我坐了一会儿，把那天没做完的数学做完，做到第四页的最后一道。</p><p>做完我看了一眼手机。屏幕上是我们刚才的对话，从头到尾。我从上往下翻了一遍，翻到最先那句。</p><p>「你怎么还没删我」</p><p>我对着这句话想了很久。</p><p>如果她那句话问的是真的，那说明在她那边，这半年她也想过我会删她。她大概想过很多次。她大概觉得，一个人消失半年，另一个人有充分的理由把他删掉。</p><p>可更让我在意的是另外一件事。</p><p>她第一句话不是问我过得好不好，也不是说她回来了。她第一句话是在确认，我这边是不是还留着门。</p><p>她那晚回来，不是因为她想说她想我。是因为她想看看，那个位置还在不在。</p><p>第二天晚上她准时来了。</p><p>第三天也来了。</p><p>她像是把那半年的事，全部记在了另一个地方，这边不留一点痕迹。我们接着从冬天往下聊，好像中间什么都没发生。</p><p>可我知道发生了什么。</p><p>那几天我一直在想一个问题：要不要问。</p><p>我把这个问题想过很多次。吃饭的时候想，走路的时候想。我甚至想了开场白，想了怎么问才不显得像在追究。有一晚上我把一句问话写了又删，删了又写，最后屏幕上只剩下一个空格。</p><p>可我没问。</p><p>我怕问了，她就不来了。</p><p>人的想法有时候就是这么小气。你手里捏着一件很容易碎的东西，你就不敢碰它。</p><p>腊月二十八那天她没来。</p><p>我从晚上八点等到十二点。第二天她才来，说家里来客人了。</p><p>我说好。</p><p>她说，你等到几点。</p><p>我说，没等，我写作业来着。</p><p>她说，骗人。</p><p>我说，真的。</p><p>她说，你这个人。</p><p>那三天我发现一件事：我居然会数时间了。她八点来和十点来，对我不是一回事。我在心里记了这几天她几点上线，记完我自己都觉得可笑。</p><p>我没跟她说。</p><p>奶奶那几天也看出点什么了。她问我，是不是快过年了这么高兴。</p><p>我说，嗯。</p><p>她说，高兴也别老熬夜，眼睛都红了。</p><p>我说，知道了。</p><p>那半年我做了什么，我记得清清楚楚。我在一个汽车站坐了四十分钟，然后回的家。我给她写了一封没有地方寄的信。我把零花钱在铅笔盒里放了很久，放到纸币都软了。</p><p>还有一件事：我把她的对话框一直放在最上面。她回来之后我也没有把它移回去。</p><p>这些事她不知道。我也没打算告诉她。</p><p>那封信我重新收了一次。以前放在本子里，那晚我把本子塞到了书架最里面那排书后面。她回来了，那封信就更不能被人看到。</p><p>我甚至想过把那封信抽出来，单独放到别的地方去。想了一下，没放。分开放，早晚有一天我会忘了在哪一本里。</p><p>我想的是，她回来就好。</p><p>那年冬天我一直这么想。</p><p>那天夜里我在本子上加了一行。</p><p>我写：腊月十六，她回来了。</p><p>写完我看着那一行，没有再写别的。这一行是那本本子上唯一一条不是抄她的话的记录。</p><p>后来那本本子被我写满了，换了一本新的。这个格式我保留了下来：她说的抄一份，发生的事另外记。</p><p>两样东西分开写。我一直觉得这样比较稳妥。具体稳在哪里，我当时也说不上来。</p><p>后来我才知道，一个人消失过一次，就会消失第二次。</p>',97)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
